"""Signed-URL downloads backed by local disk — no cloud storage.

Flow
----
GET /files/{name}/sign  -> {"url": "/download/{name}?expires=<ts>&sig=<hex>"}
                           (link valid for SIGNATURE_TTL_SECONDS, injectable clock)
GET /download/{name}    -> verifies the HMAC signature AND expiry BEFORE any
                           disk access; path-traversal names are rejected with
                           a plain 404 and never reach the filesystem.

The wall clock lives behind ``get_now()`` so tests can inject a fake clock
via ``monkeypatch.setattr(srv_module, "get_now", ...)``.
"""

from __future__ import annotations

import hashlib
import hmac
import mimetypes
import time
from pathlib import Path
from typing import Iterator
from urllib.parse import quote

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse, StreamingResponse

SECRET_KEY = b"ox-alpha-signed-url-dev-secret"
SIGNATURE_TTL_SECONDS = 60
CHUNK_SIZE = 64 * 1024

# Root of everything that may be served. Tests point this at a tmp dir.
FILES_DIR = Path(__file__).resolve().parent / "storage"

app = FastAPI(title="Signed URL Downloads")


def get_now() -> float:
    """Injectable clock: returns current unix time in seconds."""
    return time.time()


def compute_sig(name: str, expires: int) -> str:
    """HMAC-SHA256 over (name + expires) under the server secret."""
    message = f"{name}{expires}".encode("utf-8")
    return hmac.new(SECRET_KEY, message, hashlib.sha256).hexdigest()


class ApiError(Exception):
    def __init__(self, status_code: int, code: str) -> None:
        self.status_code = status_code
        self.code = code


@app.exception_handler(ApiError)
async def api_error_handler(_: Request, exc: ApiError) -> JSONResponse:
    return JSONResponse(
        status_code=exc.status_code,
        content={"error": {"code": exc.code}},
    )


def safe_path(name: str) -> Path:
    """Validate *name* and resolve it strictly inside FILES_DIR.

    Raises ApiError(404) for anything suspicious. This runs before signature
    checks on download and before any open() anywhere, so traversal attempts
    never touch the filesystem.
    """
    if (
        not name
        or name in {".", ".."}
        or "/" in name
        or "\\" in name
        or "\x00" in name
    ):
        raise ApiError(404, "not_found")

    base = FILES_DIR.resolve()
    try:
        resolved = (base / name).resolve()
    except OSError:
        raise ApiError(404, "not_found")

    # Defense in depth: even a sneaky encoding must resolve back into base.
    if resolved.parent != base:
        raise ApiError(404, "not_found")
    return resolved


@app.get("/files/{name}/sign")
def sign_link(name: str) -> dict:
    safe_path(name)  # reject traversal-style names up front
    expires = int(get_now()) + SIGNATURE_TTL_SECONDS
    sig = compute_sig(name, expires)
    url = f"/download/{quote(name)}?expires={expires}&sig={sig}"
    return {"url": url, "name": name, "expires": expires}


@app.get("/download/{name}")
def download(name: str, request: Request):
    # 1) Path safety first — a 404 here happens without touching disk.
    path = safe_path(name)

    # 2) Signature + expiry verification — still no disk access.
    expires_raw = request.query_params.get("expires")
    sig = request.query_params.get("sig")
    if not expires_raw or not sig:
        raise ApiError(403, "invalid_signature")
    try:
        expires = int(expires_raw)
    except ValueError:
        raise ApiError(403, "invalid_signature")

    expected = compute_sig(name, expires)
    if not hmac.compare_digest(expected, sig):
        raise ApiError(403, "invalid_signature")
    if get_now() > expires:
        raise ApiError(403, "link_expired")

    # 3) Only now may we look at the filesystem.
    if not path.is_file():
        raise ApiError(404, "not_found")

    media_type = mimetypes.guess_type(name)[0] or "application/octet-stream"

    def stream() -> Iterator[bytes]:
        with open(path, "rb") as fh:
            while chunk := fh.read(CHUNK_SIZE):
                yield chunk

    return StreamingResponse(stream(), media_type=media_type)


@app.get("/files/{name}")
def file_meta(name: str) -> dict:
    path = safe_path(name)
    if not path.is_file():
        raise ApiError(404, "not_found")
    stat = path.stat()
    return {"name": name, "size": stat.st_size}


if __name__ == "__main__":  # pragma: no cover
    import uvicorn

    FILES_DIR.mkdir(exist_ok=True)
    uvicorn.run(app, host="127.0.0.1", port=8000)

